"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([["19593"],{8e4(e,n,r){r.r(n),r.d(n,{metadata:()=>s,default:()=>d,frontMatter:()=>a,contentTitle:()=>o,toc:()=>l,assets:()=>u});var s=JSON.parse('{"id":"projects/professionnel/api-cloud","title":"Mise en production cloud d\'une API","description":"Mise en production d\'une API web Python chez un fournisseur de cloud : infrastructure d\xe9crite en Terraform, chart Helm commun \xe0 trois environnements, livraison par GitHub Actions avec un plan d\'infrastructure relu avant d\'\xeatre appliqu\xe9, et ingestion automatique de fichiers d\xe9pos\xe9s dans un stockage objet.","source":"@site/docs/projects/professionnel/api-cloud.md","sourceDirName":"projects/professionnel","slug":"/projects/professionnel/api-cloud","permalink":"/docs/projects/professionnel/api-cloud","draft":false,"unlisted":false,"tags":[{"inline":true,"label":"terraform","permalink":"/docs/tags/terraform"},{"inline":true,"label":"kubernetes","permalink":"/docs/tags/kubernetes"},{"inline":true,"label":"helm","permalink":"/docs/tags/helm"},{"inline":true,"label":"github-actions","permalink":"/docs/tags/github-actions"},{"inline":true,"label":"cicd","permalink":"/docs/tags/cicd"},{"inline":true,"label":"docker","permalink":"/docs/tags/docker"},{"inline":true,"label":"postgresql","permalink":"/docs/tags/postgresql"}],"version":"current","lastUpdatedAt":1795348395000,"frontMatter":{"title":"Mise en production cloud d\'une API","description":"Mise en production d\'une API web Python chez un fournisseur de cloud : infrastructure d\xe9crite en Terraform, chart Helm commun \xe0 trois environnements, livraison par GitHub Actions avec un plan d\'infrastructure relu avant d\'\xeatre appliqu\xe9, et ingestion automatique de fichiers d\xe9pos\xe9s dans un stockage objet.","tags":["terraform","kubernetes","helm","github-actions","cicd","docker","postgresql"]},"sidebar":"tutorialSidebar","previous":{"title":"Professionnel","permalink":"/docs/projects/professionnel/"},"next":{"title":"BlueNav - Jumeau num\xe9rique bateau autonome","permalink":"/docs/projects/professionnel/bluenav-jumeau-numerique"}}'),t=r(74848),i=r(28453);let a={title:"Mise en production cloud d'une API",description:"Mise en production d'une API web Python chez un fournisseur de cloud : infrastructure d\xe9crite en Terraform, chart Helm commun \xe0 trois environnements, livraison par GitHub Actions avec un plan d'infrastructure relu avant d'\xeatre appliqu\xe9, et ingestion automatique de fichiers d\xe9pos\xe9s dans un stockage objet.",tags:["terraform","kubernetes","helm","github-actions","cicd","docker","postgresql"]},o,u={},l=[{value:"Contexte",id:"contexte",level:2},{value:"Architecture",id:"architecture",level:2},{value:"Infrastructure Terraform",id:"infrastructure-terraform",level:2},{value:"Chart Helm",id:"chart-helm",level:2},{value:"Cha\xeene de livraison",id:"cha\xeene-de-livraison",level:2},{value:"Ingestion des fichiers d\xe9pos\xe9s",id:"ingestion-des-fichiers-d\xe9pos\xe9s",level:2},{value:"Exploitation",id:"exploitation",level:2},{value:"R\xf4le",id:"r\xf4le",level:2},{value:"R\xe9sultats",id:"r\xe9sultats",level:2},{value:"Limites connues",id:"limites-connues",level:2},{value:"Liens",id:"liens",level:2}];function c(e){let n={a:"a",h2:"h2",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components},{ProjectMeta:r}=n;return r||function(e,n){throw Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("ProjectMeta",!0),(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(r,{start:"2026",role:"Infrastructure, CI/CD et exploitation",domain:"Mise en production cloud, infrastructure as code, livraison continue",stack:["Terraform","Kubernetes","Helm","GitHub Actions","Docker","PostgreSQL","Traefik","Python"]}),"\n",(0,t.jsx)(n.h2,{id:"contexte",children:"Contexte"}),"\n",(0,t.jsx)(n.p,{children:"L'application est une API web \xe9crite en Python, consomm\xe9e par une interface d\xe9velopp\xe9e \xe0 part. Elle tournait d'abord en test et en pr\xe9production sur le cluster Kubernetes interne de l'\xe9quipe, avec sa base de donn\xe9es et son stockage de fichiers install\xe9s dans le cluster. Son ouverture \xe0 de premiers utilisateurs demandait une vraie production, h\xe9berg\xe9e chez un fournisseur de cloud, avec une base de donn\xe9es et un stockage g\xe9r\xe9s par ce fournisseur."}),"\n",(0,t.jsx)(n.p,{children:"Le travail couvrait toute la cha\xeene qui m\xe8ne le code jusqu'\xe0 la production : l'infrastructure, le paquet de d\xe9ploiement de l'application, la livraison continue et l'exploitation. S'y ajoutait l'ingestion automatique des fichiers de donn\xe9es qu'un syst\xe8me externe d\xe9pose r\xe9guli\xe8rement."}),"\n",(0,t.jsx)(n.h2,{id:"architecture",children:"Architecture"}),"\n",(0,t.jsx)(n.mermaid,{value:'flowchart TD\n  users["Utilisateurs"] --\x3e entree["Entr\xe9e HTTPS<br/>adresse r\xe9serv\xe9e"]\n  subgraph reseau["R\xe9seau priv\xe9"]\n    entree --\x3e api["API"]\n    entree --\x3e front["Interface"]\n    ingest["Ingestion<br/>des fichiers"]\n    api --\x3e db[("Base de donn\xe9es<br/>g\xe9r\xe9e")]\n    ingest --\x3e db\n  end\n  depot["Syst\xe8me externe"] --\x3e|d\xe9pose| bucket[("Stockage objet")]\n  ingest --\x3e|"interroge"| bucket\n  ci["GitHub Actions"] --\x3e|"Terraform, Helm"| reseau'}),"\n",(0,t.jsx)(n.p,{children:"L'application tourne dans un cluster Kubernetes g\xe9r\xe9 par le fournisseur, plac\xe9 avec la base de donn\xe9es dans un r\xe9seau priv\xe9 : la base n'est joignable que de l'int\xe9rieur. Seule l'entr\xe9e HTTPS, sur une adresse publique r\xe9serv\xe9e, re\xe7oit le trafic des utilisateurs. Les fichiers de l'application et ceux du syst\xe8me externe vivent dans des espaces de stockage objet s\xe9par\xe9s."}),"\n",(0,t.jsx)(n.h2,{id:"infrastructure-terraform",children:"Infrastructure Terraform"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Deux ensembles ind\xe9pendants."})," Le premier d\xe9crit le socle chez le fournisseur : r\xe9seau, cluster, base de donn\xe9es, stockage et noms de domaine. Le second installe dans le cluster ce dont l'application a besoin pour fonctionner : l'entr\xe9e HTTPS, la gestion automatique des certificats et la configuration qui relie l'application \xe0 son socle. Terraform ne sait pas configurer l'acc\xe8s \xe0 un cluster qu'il cr\xe9e dans le m\xeame ensemble, et la s\xe9paration limite la port\xe9e d'une erreur : une modification du second ne peut pas toucher la base. Le second lit les sorties du premier, sans rien recopier. L'\xe9tat des deux est conserv\xe9 dans un stockage objet versionn\xe9, avec un verrou qui emp\xeache deux modifications simultan\xe9es ; l'article ",(0,t.jsx)(n.a,{href:"/blog/2026/07/11/08-iac/terraform-remote-state",children:"Terraform : state remote avec S3"})," d\xe9crit ce m\xe9canisme."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Une identit\xe9 par usage."})," L'application de l'infrastructure, sa simple lecture par l'int\xe9gration continue, l'application elle-m\xeame et le syst\xe8me externe ont chacun leurs propres acc\xe8s, limit\xe9s \xe0 ce dont ils ont besoin. Le syst\xe8me externe, par exemple, ne voit que l'espace o\xf9 il d\xe9pose ses fichiers."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Des secrets hors de l'\xe9tat."})," Le mot de passe de la base n'est jamais \xe9crit dans l'\xe9tat de Terraform, et le changer revient \xe0 incr\xe9menter un num\xe9ro de version. L'adresse priv\xe9e de la base change quand le r\xe9seau est recr\xe9\xe9 : Terraform la publie dans une configuration que l'application lit au d\xe9marrage, au lieu de la recopier \xe0 la main dans les param\xe8tres de d\xe9ploiement."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Des ressources prot\xe9g\xe9es."})," La base, le stockage, le r\xe9seau et l'adresse publique sont prot\xe9g\xe9s contre une destruction accidentelle ; le cluster ne l'est pas, puisqu'il se recr\xe9e depuis le code. Ces protections s'appuient sur les m\xe9canismes d\xe9crits dans ",(0,t.jsx)(n.a,{href:"/blog/2026/07/11/08-iac/terraform-depends-on-lifecycle",children:"Terraform : depends_on et lifecycle"}),". L'entr\xe9e HTTPS transmet \xe0 l'application l'adresse r\xe9elle de chaque client, sans quoi les limites de d\xe9bit s'appliqueraient \xe0 tous les utilisateurs \xe0 la fois."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Une production qui peut se mettre en pause."})," Sans utilisateur, la production peut \xeatre suspendue : le cluster et la base sont d\xe9truits, le r\xe9seau, l'adresse publique et le stockage sont gard\xe9s. L'ordre compte. L'\xe9quilibreur de charge est cr\xe9\xe9 par Kubernetes et non par Terraform : s'il n'est pas supprim\xe9 avant le cluster, il lui survit, reste factur\xe9 et garde l'adresse r\xe9serv\xe9e. La proc\xe9dure de pause et de reprise impose donc cet ordre."]}),"\n",(0,t.jsx)(n.h2,{id:"chart-helm",children:"Chart Helm"}),"\n",(0,t.jsx)(n.p,{children:"Un seul chart Helm sert au test, \xe0 la pr\xe9production et \xe0 la production ; la production ne diff\xe8re que par son fichier de param\xe8tres. En test et en pr\xe9production, le chart embarque sa propre base de donn\xe9es et son propre stockage, et s'expose derri\xe8re l'authentification commune du cluster interne. En production, il les d\xe9sactive, lit la configuration pos\xe9e par Terraform et publie une entr\xe9e avec son certificat."}),"\n",(0,t.jsx)(n.p,{children:"Les migrations de la base passent par une t\xe2che d\xe9di\xe9e, lanc\xe9e \xe0 chaque nouvelle version. L'API et l'ingestion attendent que la base soit \xe0 jour avant de d\xe9marrer. Si les migrations \xe9chouent, le d\xe9ploiement n'aboutit pas dans le temps imparti et Helm revient de lui-m\xeame \xe0 la version pr\xe9c\xe9dente ; l'API continue de r\xe9pondre pendant ce retour arri\xe8re, ce qui a \xe9t\xe9 v\xe9rifi\xe9 en provoquant volontairement l'\xe9chec."}),"\n",(0,t.jsxs)(n.p,{children:["Les services ne red\xe9marrent que si leur configuration ou leurs secrets changent r\xe9ellement : red\xe9ployer \xe0 l'identique ne relance rien. Tous les conteneurs tournent sans droits d'administrateur, sur un syst\xe8me de fichiers en lecture seule. Les ressources r\xe9serv\xe9es pour chaque service viennent d'une semaine de mesures. L'image est d\xe9sign\xe9e par une \xe9tiquette fixe, tir\xe9e du commit qui l'a produite, selon le principe d\xe9crit dans ",(0,t.jsx)(n.a,{href:"/blog/2026/09/24/04-ci-cd/helm-tag-immuable",children:"Helm : d\xe9ploiement par tag immuable"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"cha\xeene-de-livraison",children:"Cha\xeene de livraison"}),"\n",(0,t.jsx)(n.mermaid,{value:'flowchart TD\n  pr["Demande de fusion<br/>tests, plan"] --\x3e merge["Fusion"]\n  merge --\x3e test["Test<br/>image construite"]\n  test --\x3e preprod["Pr\xe9production<br/>m\xeame image, tests"]\n  preprod --\x3e brouillon["Brouillon<br/>de publication"]\n  brouillon --\x3e|"relu, publi\xe9"| infra["Infrastructure<br/>appliqu\xe9e"]\n  infra --\x3e prod["Production<br/>d\xe9ploy\xe9e"]'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Une image construite une seule fois."})," Chaque version est construite une fois, test\xe9e, puis promue telle quelle en pr\xe9production et en production, sans \xeatre reconstruite. La production ex\xe9cute donc exactement l'image qui a pass\xe9 les tests. L'image est organis\xe9e pour qu'un simple changement de num\xe9ro de version n'oblige pas \xe0 r\xe9installer les d\xe9pendances : en local, sa reconstruction passe de plus d'une minute et demie \xe0 quelques secondes."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Un plan relu avant d'\xeatre appliqu\xe9."})," Avant chaque mise en production, un brouillon de publication rassemble tout ce qui va changer : les diff\xe9rences du d\xe9ploiement, les migrations pr\xe9vues sur la base de production et le plan de Terraform. Publier ce brouillon vaut validation. Au moment d'appliquer, le plan est recalcul\xe9 et compar\xe9 \xe0 celui qui a \xe9t\xe9 relu, au moyen d'une empreinte qui r\xe9sume la liste des changements sans en r\xe9v\xe9ler aucune valeur. Si le plan a chang\xe9 entre-temps, rien n'est appliqu\xe9."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Des suppressions refus\xe9es par d\xe9faut."})," Un plan qui supprime ou remplace une ressource est refus\xe9 par la cha\xeene automatique. Une suppression voulue passe par un lancement manuel, avec une confirmation explicite. Deux modifications d'un m\xeame ensemble ne se chevauchent jamais, et une modification en cours n'est jamais interrompue."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Un acc\xe8s au cluster toujours \xe0 jour."})," Apr\xe8s une reprise, le cluster recr\xe9\xe9 change d'adresse. La cha\xeene lit donc l'acc\xe8s au cluster dans les sorties de Terraform \xe0 chaque ex\xe9cution, au lieu de le garder dans un secret qui deviendrait p\xe9rim\xe9, et refuse tout cluster qui n'est pas celui de la production."]}),"\n",(0,t.jsx)(n.h2,{id:"ingestion-des-fichiers-d\xe9pos\xe9s",children:"Ingestion des fichiers d\xe9pos\xe9s"}),"\n",(0,t.jsx)(n.p,{children:"Le syst\xe8me externe d\xe9pose des fichiers de mesures et des jeux de donn\xe9es de r\xe9f\xe9rence dans un stockage objet. En test et en pr\xe9production, chaque d\xe9p\xf4t d\xe9clenchait un traitement par notification. Le stockage du fournisseur ne propose pas ces notifications : elles ont \xe9t\xe9 remplac\xe9es par un service permanent qui interroge le stockage chaque minute. Une t\xe2che planifi\xe9e a \xe9t\xe9 \xe9cart\xe9e, parce qu'elle relancerait toute l'application \xe0 chaque passage et n'emp\xeacherait pas deux passages longs de se chevaucher. Le stockage \xe9tant versionn\xe9, chaque d\xe9p\xf4t garde une identit\xe9 propre, m\xeame quand le m\xeame fichier est d\xe9pos\xe9 deux fois."}),"\n",(0,t.jsx)(n.p,{children:"\xc0 chaque passage, le service compare ce qui est d\xe9pos\xe9 \xe0 ce qui a d\xe9j\xe0 \xe9t\xe9 trait\xe9, et d\xe9cide pour chaque fichier de le traiter, de l'ignorer ou de le signaler comme non reconnu. Un stockage d\xe9j\xe0 trait\xe9 ne co\xfbte qu'une liste et une requ\xeate. Un verrou pris dans la base garantit qu'un m\xeame fichier n'est jamais trait\xe9 deux fois en m\xeame temps, m\xeame si un rejeu manuel tourne en parall\xe8le."}),"\n",(0,t.jsx)(n.p,{children:"Les erreurs sont class\xe9es. Un fichier au contenu invalide est marqu\xe9 en \xe9chec. Une panne passag\xe8re du stockage laisse le fichier pour le passage suivant, et une s\xe9rie de pannes arr\xeate le passage au lieu d'insister. Un jeu de r\xe9f\xe9rence est refus\xe9 en entier s'il contient une seule entr\xe9e invalide : un import automatique partiel passerait inaper\xe7u. Un fichier de mesures arriv\xe9 avant le jeu de r\xe9f\xe9rence dont il d\xe9pend est rejou\xe9 automatiquement apr\xe8s l'import de ce dernier, et une commande permet de rejouer les \xe9checs \xe0 la main."}),"\n",(0,t.jsx)(n.p,{children:"Une seule instance du service existe \xe0 la fois. Elle termine le fichier en cours avant de s'arr\xeater, refuse de d\xe9marrer si le stockage n'est pas versionn\xe9, et Kubernetes la red\xe9marre si elle cesse de donner signe de vie."}),"\n",(0,t.jsx)(n.h2,{id:"exploitation",children:"Exploitation"}),"\n",(0,t.jsx)(n.p,{children:"La documentation d'exploitation est \xe9crite pour qu'un coll\xe8gue puisse reprendre la production sans son auteur : acc\xe8s et proc\xe9dure en cas de perte, pr\xe9paration du poste, renouvellement des cl\xe9s et du mot de passe, pause et reprise, reconstruction compl\xe8te depuis un compte vide. Un manuel d'urgence d\xe9crit la mise en production \xe0 la main quand l'int\xe9gration continue est indisponible."}),"\n",(0,t.jsx)(n.p,{children:"La base est sauvegard\xe9e chaque jour, avec sept jours de r\xe9tention. La restauration passe par une base temporaire, d'o\xf9 les donn\xe9es sont recopi\xe9es dans la base de production, application arr\xeat\xe9e ; la production garde ainsi sa base, son adresse et sa description dans Terraform."}),"\n",(0,t.jsx)(n.h2,{id:"r\xf4le",children:"R\xf4le"}),"\n",(0,t.jsx)(n.p,{children:"Trois d\xe9veloppeurs ont contribu\xe9 \xe0 l'application. Ma part couvre l'infrastructure Terraform, le chart Helm, l'image Docker, les workflows GitHub Actions, le service d'ingestion et la documentation de d\xe9ploiement et d'exploitation, ainsi que, c\xf4t\xe9 application, la gestion des donn\xe9es de r\xe9f\xe9rence aliment\xe9es par l'ingestion. Un coll\xe8gue a \xe9crit l'essentiel de l'API m\xe9tier et ses tests. Un second coll\xe8gue a mis en place les journaux structur\xe9s, la supervision locale et les tests de bout en bout lanc\xe9s sur la pr\xe9production."}),"\n",(0,t.jsx)(n.h2,{id:"r\xe9sultats",children:"R\xe9sultats"}),"\n",(0,t.jsx)(n.p,{children:"La production est en service pour de premiers utilisateurs. Elle n'est d\xe9ploy\xe9e que par l'int\xe9gration continue, \xe0 la publication d'une version ; les interventions manuelles sont r\xe9serv\xe9es \xe0 la pause, \xe0 la reprise et \xe0 la reconstruction. Avant la mise en service, les droits de chaque identit\xe9 ont \xe9t\xe9 test\xe9s un par un, et la protection de la base contre la destruction a \xe9t\xe9 v\xe9rifi\xe9e. Les fichiers du syst\xe8me externe sont ing\xe9r\xe9s sans intervention : l'import manuel apr\xe8s chaque d\xe9p\xf4t n'existe plus."}),"\n",(0,t.jsx)(n.h2,{id:"limites-connues",children:"Limites connues"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Le cluster ne compte qu'un n\u0153ud : chaque mise \xe0 jour, y compris celles que le fournisseur applique automatiquement chaque semaine, coupe le service quelques minutes. Un second n\u0153ud supprimerait la coupure."}),"\n",(0,t.jsx)(n.li,{children:"Les journaux de la production ne sont pas encore collect\xe9s par l'outil de supervision du fournisseur ; les alertes et le tableau de bord ont \xe9t\xe9 mis au point sur la supervision locale."}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"liens",children:"Liens"}),"\n",(0,t.jsx)(n.p,{children:"Le d\xe9p\xf4t est priv\xe9."})]})}function d(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}},28453(e,n,r){r.d(n,{R:()=>a,x:()=>o});var s=r(96540);let t={},i=s.createContext(t);function a(e){let n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);